drafts.2:
h1 {
  text-align: center;
  font-size: 32px;
}

p {
  text-align: center;
}

drafts.4:
ul {
  display: flex;
  list-style: none;
}

a {
  text-decoration: none;
}

drafts.5:
table {
  width: 100%;
  border-collapse: collapse;
}

th, td {
  border: 1px solid #94a3b8;
  padding: 8px;
}

th {
  background-color: #bfdbfe;
}

drafts.6:
form {
  padding: 16px;
  background-color: #f1f5f9;
  border-radius: 10px;
}

input {
  width: 100%;
  box-sizing: border-box;
}

drafts.7:
.card {
  max-width: 360px;
  margin: 20px auto;
  padding: 16px;
  background-color: #ffffff;
  border: 1px solid #cbd5e1;
  border-radius: 12px;
  box-shadow: 0 4px 12px #0f172a18;
}
